contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 loanID, address to) public {
        // Precondition: the loan identified by loanID has no lender set.
        require(c.getLoan(loanID).lender == address(0));

        bool reverted;
        try c.approveTransfer(to, loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: only the current lender of an existing loan may approve a
        // transfer; when no lender exists (zero address), the call must revert.
        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        require(amount <= 1e18);

        uint256 interest = c.interestFor(amount, 1e18, 365 days);

        // Rule: a 100% annual rate (1e18) over exactly one year charges
        // interest equal to the principal, for any amount within bounds.
        assert(interest == amount);
    }

    receive() external payable {}
}

